content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --primary-light: #eff6ff;
  --primary-focus: rgba(37, 99, 235, 0.25);

  --secondary-color: #0f172a;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --text-light: #94a3b8;

  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-subtle: #f1f5f9;

  --border-color: #e2e8f0;
  --border-focus: #3b82f6;

  --accent-color: #059669;
  --accent-light: #ecfdf5;
  --warning-color: #d97706;
  --warning-light: #fef3c7;
  --danger-color: #dc2626;
  --danger-light: #fee2e2;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリケーションコンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

@media (min-width: 768px) {
  .app-container {
    padding: 36px 24px 64px;
  }
}

/* ヘッダー */
.app-header {
  text-align: center;
  margin-bottom: 28px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--secondary-color);
  letter-spacing: -0.025em;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 6px;
}

@media (min-width: 768px) {
  .header-title {
    font-size: 2.25rem;
  }
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* メインレイアウト */
.simulator-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 992px) {
  .simulator-layout {
    grid-template-columns: 420px 1fr;
    align-items: start;
  }
}

/* 各種カード共通 */
.input-card,
.summary-card,
.chart-card,
.table-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

@media (min-width: 768px) {
  .input-card,
  .summary-card,
  .chart-card,
  .table-card {
    padding: 24px;
  }
}

.input-card:hover,
.summary-card:hover {
  box-shadow: var(--shadow-md);
}

.chart-card:hover,
.table-card:hover {
  box-shadow: var(--shadow-lg);
}

/* 入力フォーム */
.form-group {
  margin-bottom: 20px;
}

.form-group:last-child {
  margin-bottom: 0;
}

.form-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--secondary-color);
  margin-bottom: 8px;
}

.form-helper {
  font-size: 0.775rem;
  color: var(--text-muted);
  font-weight: normal;
}

.input-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.input-number {
  flex: 1;
  width: 100%;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-main);
  background-color: var(--bg-card);
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.input-number:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--primary-focus);
}

.unit-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
  white-space: nowrap;
}

.input-slider {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--bg-subtle);
  border-radius: var(--radius-full);
  outline: none;
  margin-top: 4px;
}

.input-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  border: 2px solid #ffffff;
  box-shadow: var(--shadow-sm);
  transition: transform 0.1s ease, background-color 0.1s ease;
}

.input-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--primary-hover);
}

.input-slider::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary-color);
  cursor: pointer;
  border: 2px solid #ffffff;
  box-shadow: var(--shadow-sm);
  transition: transform 0.1s ease, background-color 0.1s ease;
}

/* ラジオボタングループ */
.radio-group {
  display: flex;
  gap: 10px;
  width: 100%;
}

.radio-label {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 14px;
  font-size: 0.9rem;
  font-weight: 600;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  background-color: var(--bg-card);
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.radio-label:has(.radio-input:checked) {
  border-color: var(--primary-color);
  background-color: var(--primary-light);
  color: var(--primary-color);
}

.radio-input {
  width: 16px;
  height: 16px;
  accent-color: var(--primary-color);
  cursor: pointer;
}

/* サマリーカード */
.summary-card {
  background: linear-gradient(135deg, #ffffff 0%, var(--bg-subtle) 100%);
  margin-bottom: 24px;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (min-width: 640px) {
  .summary-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.summary-item {
  background: var(--bg-card);
  padding: 14px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
}

.summary-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.summary-value {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--secondary-color);
  letter-spacing: -0.02em;
  display: flex;
  align-items: baseline;
  gap: 2px;
  flex-wrap: wrap;
}

.highlight-value {
  color: var(--primary-color);
}

.warning-value {
  color: var(--warning-color);
}

.danger-value {
  color: var(--danger-color);
}

/* 利息項目へのCSS変数適用 */
.summary-item:nth-child(4) .summary-value {
  color: var(--warning-color);
}

.summary-unit {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
}

.summary-subtext,
.summary-item .form-helper {
  margin-top: 4px;
}

/* チャートカード */
.chart-card {
  margin-bottom: 24px;
}

.chart-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 12px;
  margin-bottom: 16px;
}

.chart-tab-btn {
  padding: 6px 14px;
  font-size: 0.875rem;
  font-weight: 600;
  border: none;
  background: none;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.chart-tab-btn:hover {
  background-color: var(--bg-subtle);
  color: var(--text-main);
}

.chart-tab-btn-active {
  background-color: var(--primary-light);
  color: var(--primary-color);
}

.chart-tab-btn-active:hover {
  background-color: var(--primary-light);
  color: var(--primary-color);
}

.chart-container {
  width: 100%;
  height: 320px;
  min-height: 320px;
  position: relative;
}

@media (min-width: 768px) {
  .chart-container {
    height: 360px;
  }
}

/* スケジュール詳細テーブル */
.table-card {
  margin-top: 24px;
}

.table-header-bar,
.table-card > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.table-title-group,
.table-card > div:first-child > div:first-child {
  display: flex;
  align-items: center;
  gap: 8px;
}

.table-title,
.table-card h2 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--secondary-color);
}

.schedule-table-wrapper {
  max-height: 480px;
  overflow-y: auto;
  overflow-x: auto;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  margin-top: 16px;
  background-color: var(--bg-card);
}

/* border-collapse: collapse による角丸欠けを防ぐため separate + border-spacing: 0 を採用 */
.schedule-table {
  width: 100%;
  min-width: 580px;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.875rem;
  text-align: right;
}

.table-header {
  background-color: var(--bg-subtle);
  color: var(--secondary-color);
  font-weight: 700;
  position: sticky;
  top: 0;
  z-index: 1;
}

.table-header th {
  padding: 10px 14px;
  background-color: var(--bg-subtle);
  border-bottom: 1.5px solid var(--border-color);
}

.table-header th:first-child,
.table-row td:first-child {
  text-align: center;
}

.table-row {
  transition: background-color 0.15s ease;
}

.table-row:nth-child(even) {
  background-color: #fafbfc;
}

.table-row:hover {
  background-color: var(--primary-light);
}

.table-row td {
  padding: 10px 14px;
  color: var(--text-main);
  border-bottom: 1px solid var(--border-color);
}

.table-row:last-child td {
  border-bottom: none;
}

.table-row td:last-child {
  font-weight: 600;
}

/* トグルボタン & バッジ */
.toggle-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--primary-color);
  background-color: var(--primary-light);
  border: 1px solid rgba(37, 99, 235, 0.2);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 0.2s ease;
}

.toggle-btn:hover {
  background-color: #dbeafe;
}

.badge {
  display: inline-block;
  font-size: 0.725rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-full);
}

.badge-primary {
  background-color: var(--primary-light);
  color: var(--primary-color);
}

.badge-warning {
  background-color: var(--warning-light);
  color: var(--warning-color);
}

.badge-danger {
  background-color: var(--danger-light);
  color: var(--danger-color);
}

/* ユーティリティクラス */
.text-warning {
  color: var(--warning-color);
}

.text-danger {
  color: var(--danger-color);
}

.font-semibold {
  font-weight: 600;
}

.shadow-lg {
  box-shadow: var(--shadow-lg);
}

/**
 * チャート表示タブの種別 ('area': 残債推移, 'pie': 返済内訳)
 */
export type ChartTabType = 'area' | 'pie';

export interface LoanInputState {
  principal: number; // 借入額 (円)
  interestRate: number; // 年利 (%)
  years: number; // 返済年数
  repaymentType: 'equal-payment' | 'equal-principal'; // 元利均等 | 元金均等
  bonusAmount: number; // ボーナス1回あたりの加算額 (円, 年2回)
}

export interface YearlyScheduleItem {
  year: number; // 経過年
  balance: number; // 残債 (円)
  principalPaid: number; // 年間元金返済額 (円)
  interestPaid: number; // 年間利息返済額 (円)
  cumulativePrincipal: number; // 元金返済累計 (円)
  cumulativeInterest: number; // 利息返済累計 (円)
  bonusPaid?: number; // 年間ボーナス返済額 (円, 元金＋利息)
}

export interface LoanCalculationResult {
  monthlyPayment: number; // 毎月の返済額 (元金均等の場合は初回または平均、元利均等なら一定)
  monthlyPaymentMax?: number; // 元金均等返済時の初回最高支払額
  monthlyPaymentMin?: number; // 元金均等返済時の最終回支払額 (最低額)
  bonusPayment: number; // ボーナス月返済加算額 (円)
  totalPayment: number; // 総返済額 (円)
  totalInterest: number; // 利息総額 (円)
  schedule: YearlyScheduleItem[]; // 年次返済スケジュール一覧
}

export interface LoanInputFormProps {
  inputs: LoanInputState;
  onChange: (inputs: LoanInputState) => void;
}

export interface LoanChartProps {
  schedule: YearlyScheduleItem[];
  principal: number;
  totalInterest: number;
}

import { LoanInputState, LoanCalculationResult, YearlyScheduleItem } from '../types';

/**
 * 住宅ローンの元利均等・元金均等返済をシミュレーション計算するユーティリティ関数
 * 
 * @param inputs LoanInputState (借入額、金利%、年数、返済方式、ボーナス加算額)
 * @returns LoanCalculationResult (毎月返済額、総返済額、利息総額、年次スケジュール配列)
 */
export const calculateLoan = (inputs: LoanInputState): LoanCalculationResult => {
  const {
    principal = 35000000,
    interestRate = 0.5,
    years = 35,
    repaymentType = 'equal-payment',
    bonusAmount = 0,
  } = inputs;

  const totalMonths = Math.max(1, Math.round(years * 12));
  const monthlyRate = interestRate / 100 / 12;
  const bonusTimes = years * 2;

  // ボーナス返済分の元金按分
  // 一般的な住宅ローン実務ルールに準拠し、ボーナス返済元金は借入元金の50%を上限として安全ガード
  const maxBonusPrincipal = Math.floor(principal * 0.5);
  let bonusPrincipal = 0;
  let effectiveBonusAmount = bonusAmount;

  if (bonusAmount > 0 && bonusTimes > 0) {
    if (monthlyRate === 0) {
      bonusPrincipal = Math.min(maxBonusPrincipal, bonusAmount * bonusTimes);
    } else {
      const halfYearRate = interestRate / 100 / 2;
      // 半年ごとの年金現価係数を用いてボーナス加算額からボーナス元金を逆算
      const pvBonus = bonusAmount * ((1 - Math.pow(1 + halfYearRate, -bonusTimes)) / halfYearRate);
      bonusPrincipal = Math.min(maxBonusPrincipal, Math.round(pvBonus));

      // 元金上限に達した場合、1回あたりのボーナス返済額を元金に合わせて再計算
      if (pvBonus > maxBonusPrincipal) {
        effectiveBonusAmount = Math.round(
          (maxBonusPrincipal * halfYearRate) / (1 - Math.pow(1 + halfYearRate, -bonusTimes))
        );
      }
    }
  }

  const monthlyPrincipal = Math.max(0, principal - bonusPrincipal);

  let monthlyPayment = 0;
  let monthlyPaymentMax: number | undefined = undefined;
  let monthlyPaymentMin: number | undefined = undefined;
  let totalInterest = 0;
  let currentBalance = principal;
  let cumulativePrincipal = 0;
  let cumulativeInterest = 0;

  const schedule: YearlyScheduleItem[] = [];

  if (repaymentType === 'equal-payment') {
    // 元利均等返済 (毎月均等)
    if (monthlyRate === 0) {
      monthlyPayment = Math.round(monthlyPrincipal / totalMonths);
    } else {
      const factor = Math.pow(1 + monthlyRate, totalMonths);
      monthlyPayment = Math.round((monthlyPrincipal * monthlyRate * factor) / (factor - 1));
    }

    let monthlyBalance = monthlyPrincipal;
    const halfYearRate = interestRate / 100 / 2;
    let bonusBalance = bonusPrincipal;

    let yearPrincipalPaid = 0;
    let yearInterestPaid = 0;
    let yearBonusPaid = 0;

    for (let month = 1; month <= totalMonths; month++) {
      // 毎月分の利息と元金
      const interestThisMonth = monthlyBalance * monthlyRate;
      let principalThisMonth = monthlyPayment - interestThisMonth;

      if (month === totalMonths) {
        principalThisMonth = monthlyBalance;
      }

      monthlyBalance = Math.max(0, monthlyBalance - principalThisMonth);
      yearPrincipalPaid += principalThisMonth;
      yearInterestPaid += interestThisMonth;

      // ボーナス月（6ヶ月ごと: 6, 12, 18...）
      if (month % 6 === 0 && bonusBalance > 0) {
        const bonusInterest = bonusBalance * halfYearRate;
        let bonusPrincipalPaid = effectiveBonusAmount - bonusInterest;
        if (month === totalMonths || bonusPrincipalPaid > bonusBalance) {
          bonusPrincipalPaid = bonusBalance;
        }
        bonusBalance = Math.max(0, bonusBalance - bonusPrincipalPaid);
        yearPrincipalPaid += bonusPrincipalPaid;
        yearInterestPaid += bonusInterest;
        yearBonusPaid += bonusPrincipalPaid + bonusInterest;
      }

      // 1年経過時または最終月に年次スケジュールを記録
      if (month % 12 === 0 || month === totalMonths) {
        const currentYear = Math.ceil(month / 12);
        cumulativePrincipal += yearPrincipalPaid;
        cumulativeInterest += yearInterestPaid;
        currentBalance = Math.max(0, principal - cumulativePrincipal);

        schedule.push({
          year: currentYear,
          balance: Math.round(currentBalance),
          principalPaid: Math.round(yearPrincipalPaid),
          interestPaid: Math.round(yearInterestPaid),
          cumulativePrincipal: Math.round(cumulativePrincipal),
          cumulativeInterest: Math.round(cumulativeInterest),
          bonusPaid: Math.round(yearBonusPaid),
        });

        yearPrincipalPaid = 0;
        yearInterestPaid = 0;
        yearBonusPaid = 0;
      }
    }

    totalInterest = cumulativeInterest;
  } else {
    // 元金均等返済 (元金を等分割し、残高に応じた利息を上乗せ)
    const baseMonthlyPrincipal = monthlyPrincipal / totalMonths;
    const baseBonusPrincipal = bonusTimes > 0 ? bonusPrincipal / bonusTimes : 0;

    // 初回支払額 (最大支払額)
    const firstMonthInterest = monthlyPrincipal * monthlyRate;
    monthlyPaymentMax = Math.round(baseMonthlyPrincipal + firstMonthInterest);

    // 最終月支払額 (最低支払額: 最終月元金 + 最終月利息)
    const lastMonthInterest = baseMonthlyPrincipal * monthlyRate;
    monthlyPaymentMin = Math.round(baseMonthlyPrincipal + lastMonthInterest);

    let monthlyBalance = monthlyPrincipal;
    let bonusBalance = bonusPrincipal;
    let yearPrincipalPaid = 0;
    let yearInterestPaid = 0;
    let yearBonusPaid = 0;

    for (let month = 1; month <= totalMonths; month++) {
      const interestThisMonth = monthlyBalance * monthlyRate;
      const principalThisMonth = (month === totalMonths) ? monthlyBalance : baseMonthlyPrincipal;

      monthlyBalance = Math.max(0, monthlyBalance - principalThisMonth);
      yearPrincipalPaid += principalThisMonth;
      yearInterestPaid += interestThisMonth;

      // ボーナス月
      if (month % 6 === 0 && bonusTimes > 0) {
        const halfYearRate = interestRate / 100 / 2;
        const bonusInterest = bonusBalance * halfYearRate;
        const pBonusPaid = (month === totalMonths) ? bonusBalance : baseBonusPrincipal;
        bonusBalance = Math.max(0, bonusBalance - pBonusPaid);
        yearPrincipalPaid += pBonusPaid;
        yearInterestPaid += bonusInterest;
        yearBonusPaid += pBonusPaid + bonusInterest;
      }

      if (month % 12 === 0 || month === totalMonths) {
        const currentYear = Math.ceil(month / 12);
        cumulativePrincipal += yearPrincipalPaid;
        cumulativeInterest += yearInterestPaid;
        currentBalance = Math.max(0, principal - cumulativePrincipal);

        schedule.push({
          year: currentYear,
          balance: Math.round(currentBalance),
          principalPaid: Math.round(yearPrincipalPaid),
          interestPaid: Math.round(yearInterestPaid),
          cumulativePrincipal: Math.round(cumulativePrincipal),
          cumulativeInterest: Math.round(cumulativeInterest),
          bonusPaid: Math.round(yearBonusPaid),
        });

        yearPrincipalPaid = 0;
        yearInterestPaid = 0;
        yearBonusPaid = 0;
      }
    }

    // 元金均等の代表monthlyPaymentは初回返済額
    monthlyPayment = monthlyPaymentMax;
    totalInterest = cumulativeInterest;
  }

  const totalPayment = Math.round(principal + totalInterest);

  return {
    monthlyPayment: Math.round(monthlyPayment),
    monthlyPaymentMax: monthlyPaymentMax ? Math.round(monthlyPaymentMax) : undefined,
    monthlyPaymentMin: monthlyPaymentMin ? Math.round(monthlyPaymentMin) : undefined,
    bonusPayment: Math.round(effectiveBonusAmount),
    totalPayment,
    totalInterest: Math.round(totalInterest),
    schedule,
  };
};

/**
 * 日本円の通貨フォーマット（3桁カンマ区切り）
 */
export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('ja-JP').format(Math.round(amount));
};

/**
 * 万円表記フォーマット（例: 3,500万円, 1億2,000万円, 0円, 1万円未満）
 */
export const formatManYen = (amount: number): string => {
  if (!amount || amount <= 0) {
    return '0円';
  }
  const man = amount / 10000;
  if (man < 1) {
    return '1万円未満';
  }
  if (man >= 10000) {
    const oku = Math.floor(man / 10000);
    const restMan = Math.round(man % 10000);
    return restMan > 0 ? `${oku}億${formatCurrency(restMan)}万円` : `${oku}億円`;
  }
  return `${formatCurrency(Math.round(man))}万円`;
};

import { ChangeEvent, FocusEvent, useState, useEffect } from 'react';
import { LoanInputFormProps, LoanInputState } from '../types';

const MIN_PRINCIPAL = 1000000;
const MAX_PRINCIPAL = 100000000;
const MIN_INTEREST = 0.1;
const MAX_INTEREST = 10.0;
const MIN_YEARS = 1;
const MAX_YEARS = 35;
const MIN_BONUS = 0;
const MAX_BONUS = 1000000;

const LoanInputForm = ({ inputs, onChange }: LoanInputFormProps) => {
  // 万円単位・入力文字列の一時保持用ローカルState（全消し時の入力操作性確保）
  const [principalStr, setPrincipalStr] = useState<string>(
    String(Math.round(inputs.principal / 10000))
  );
  const [interestStr, setInterestStr] = useState<string>(String(inputs.interestRate));
  const [yearsStr, setYearsStr] = useState<string>(String(inputs.years));
  const [bonusStr, setBonusStr] = useState<string>(
    String(Math.round(inputs.bonusAmount / 10000))
  );

  // 外部からの inputs 変更をローカルStateへ同期
  useEffect(() => {
    setPrincipalStr(String(Math.round(inputs.principal / 10000)));
  }, [inputs.principal]);

  useEffect(() => {
    setInterestStr(String(inputs.interestRate));
  }, [inputs.interestRate]);

  useEffect(() => {
    setYearsStr(String(inputs.years));
  }, [inputs.years]);

  useEffect(() => {
    setBonusStr(String(Math.round(inputs.bonusAmount / 10000)));
  }, [inputs.bonusAmount]);

  // 借入金額変更ハンドラー
  const handlePrincipalInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    setPrincipalStr(rawValue);
    if (rawValue.trim() !== '') {
      const parsed = Number(rawValue);
      if (!Number.isNaN(parsed) && parsed > 0) {
        const clampedYen = Math.max(MIN_PRINCIPAL, Math.min(MAX_PRINCIPAL, parsed * 10000));
        onChange({ ...inputs, principal: clampedYen });
      }
    }
  };

  const handlePrincipalBlur = (_e: FocusEvent<HTMLInputElement>) => {
    const parsed = Number(principalStr);
    const validMan = Number.isNaN(parsed) || parsed < 100 ? 100 : Math.min(10000, parsed);
    setPrincipalStr(String(validMan));
    onChange({ ...inputs, principal: validMan * 10000 });
  };

  const handlePrincipalSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = Number(e.target.value);
    setPrincipalStr(String(val));
    onChange({ ...inputs, principal: val * 10000 });
  };

  // 金利変更ハンドラー
  const handleInterestInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    setInterestStr(rawValue);
    if (rawValue.trim() !== '' && !rawValue.endsWith('.')) {
      const parsed = parseFloat(rawValue);
      if (!Number.isNaN(parsed) && parsed >= 0) {
        const clamped = Math.max(MIN_INTEREST, Math.min(MAX_INTEREST, parsed));
        onChange({ ...inputs, interestRate: clamped });
      }
    }
  };

  const handleInterestBlur = (_e: FocusEvent<HTMLInputElement>) => {
    const parsed = parseFloat(interestStr);
    const validRate = Number.isNaN(parsed) || parsed < MIN_INTEREST ? MIN_INTEREST : Math.min(MAX_INTEREST, parsed);
    const formatted = Number(validRate.toFixed(2));
    setInterestStr(String(formatted));
    onChange({ ...inputs, interestRate: formatted });
  };

  const handleInterestSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setInterestStr(String(val));
    onChange({ ...inputs, interestRate: val });
  };

  // 年数変更ハンドラー
  const handleYearsInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    setYearsStr(rawValue);
    if (rawValue.trim() !== '') {
      const parsed = parseInt(rawValue, 10);
      if (!Number.isNaN(parsed) && parsed > 0) {
        const clamped = Math.max(MIN_YEARS, Math.min(MAX_YEARS, parsed));
        onChange({ ...inputs, years: clamped });
      }
    }
  };

  const handleYearsBlur = (_e: FocusEvent<HTMLInputElement>) => {
    const parsed = parseInt(yearsStr, 10);
    const validYears = Number.isNaN(parsed) || parsed < MIN_YEARS ? MIN_YEARS : Math.min(MAX_YEARS, parsed);
    setYearsStr(String(validYears));
    onChange({ ...inputs, years: validYears });
  };

  const handleYearsSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value, 10);
    setYearsStr(String(val));
    onChange({ ...inputs, years: val });
  };

  // 返済方式変更ハンドラー
  const handleRepaymentTypeChange = (repaymentType: LoanInputState['repaymentType']) => {
    onChange({ ...inputs, repaymentType });
  };

  // ボーナス変更ハンドラー
  const handleBonusInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value;
    setBonusStr(rawValue);
    if (rawValue.trim() !== '') {
      const parsed = Number(rawValue);
      if (!Number.isNaN(parsed) && parsed >= 0) {
        const clampedYen = Math.max(MIN_BONUS, Math.min(MAX_BONUS, parsed * 10000));
        onChange({ ...inputs, bonusAmount: clampedYen });
      }
    }
  };

  const handleBonusBlur = (_e: FocusEvent<HTMLInputElement>) => {
    const parsed = Number(bonusStr);
    const validMan = Number.isNaN(parsed) || parsed < 0 ? 0 : Math.min(100, parsed);
    setBonusStr(String(validMan));
    onChange({ ...inputs, bonusAmount: validMan * 10000 });
  };

  const handleBonusSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = Number(e.target.value);
    setBonusStr(String(val));
    onChange({ ...inputs, bonusAmount: val * 10000 });
  };

  const principalInManYen = Math.round(inputs.principal / 10000);
  const bonusInManYen = Math.round(inputs.bonusAmount / 10000);

  return (
    <div className="input-card">
      {/* 借入額 */}
      <div className="form-group">
        <label className="form-label" htmlFor="principal-input">
          <span>借入金額</span>
          <span className="form-helper">100万 〜 10,000万円</span>
        </label>
        <div className="input-row">
          <input
            id="principal-input"
            type="number"
            className="input-number"
            value={principalStr}
            min={100}
            max={10000}
            step={10}
            onChange={handlePrincipalInputChange}
            onBlur={handlePrincipalBlur}
          />
          <span className="unit-label">万円</span>
        </div>
        <input
          type="range"
          className="input-slider"
          value={principalInManYen}
          min={100}
          max={10000}
          step={10}
          aria-label="借入金額スライダー"
          aria-valuemin={100}
          aria-valuemax={10000}
          aria-valuenow={principalInManYen}
          onChange={handlePrincipalSliderChange}
        />
      </div>

      {/* 借入金利 */}
      <div className="form-group">
        <label className="form-label" htmlFor="interest-input">
          <span>借入金利（年利）</span>
          <span className="form-helper">0.10% 〜 10.00%</span>
        </label>
        <div className="input-row">
          <input
            id="interest-input"
            type="number"
            className="input-number"
            value={interestStr}
            min={0.1}
            max={10.0}
            step={0.01}
            onChange={handleInterestInputChange}
            onBlur={handleInterestBlur}
          />
          <span className="unit-label">%</span>
        </div>
        <input
          type="range"
          className="input-slider"
          value={inputs.interestRate}
          min={0.1}
          max={10.0}
          step={0.01}
          aria-label="金利スライダー"
          aria-valuemin={0.1}
          aria-valuemax={10.0}
          aria-valuenow={inputs.interestRate}
          onChange={handleInterestSliderChange}
        />
      </div>

      {/* 返済年数 */}
      <div className="form-group">
        <label className="form-label" htmlFor="years-input">
          <span>返済期間</span>
          <span className="form-helper">1年 〜 35年</span>
        </label>
        <div className="input-row">
          <input
            id="years-input"
            type="number"
            className="input-number"
            value={yearsStr}
            min={1}
            max={35}
            step={1}
            onChange={handleYearsInputChange}
            onBlur={handleYearsBlur}
          />
          <span className="unit-label">年</span>
        </div>
        <input
          type="range"
          className="input-slider"
          value={inputs.years}
          min={1}
          max={35}
          step={1}
          aria-label="返済期間スライダー"
          aria-valuemin={1}
          aria-valuemax={35}
          aria-valuenow={inputs.years}
          onChange={handleYearsSliderChange}
        />
      </div>

      {/* 返済方式 */}
      <div className="form-group">
        <label className="form-label">
          <span>返済方式</span>
          <span className="form-helper">毎月の返済ルール</span>
        </label>
        <div className="radio-group">
          <label className="radio-label">
            <input
              type="radio"
              name="repaymentType"
              value="equal-payment"
              className="radio-input"
              checked={inputs.repaymentType === 'equal-payment'}
              onChange={() => handleRepaymentTypeChange('equal-payment')}
            />
            <span>元利均等返済</span>
          </label>
          <label className="radio-label">
            <input
              type="radio"
              name="repaymentType"
              value="equal-principal"
              className="radio-input"
              checked={inputs.repaymentType === 'equal-principal'}
              onChange={() => handleRepaymentTypeChange('equal-principal')}
            />
            <span>元金均等返済</span>
          </label>
        </div>
      </div>

      {/* ボーナス月加算額 */}
      <div className="form-group">
        <label className="form-label" htmlFor="bonus-input">
          <span>ボーナス加算額（年2回・1回あたり）</span>
          <span className="form-helper">0 〜 100万円</span>
        </label>
        <div className="input-row">
          <input
            id="bonus-input"
            type="number"
            className="input-number"
            value={bonusStr}
            min={0}
            max={100}
            step={1}
            onChange={handleBonusInputChange}
            onBlur={handleBonusBlur}
          />
          <span className="unit-label">万円</span>
        </div>
        <input
          type="range"
          className="input-slider"
          value={bonusInManYen}
          min={0}
          max={100}
          step={1}
          aria-label="ボーナス加算額スライダー"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={bonusInManYen}
          onChange={handleBonusSliderChange}
        />
      </div>
    </div>
  );
};

export default LoanInputForm;

import { useState } from 'react';
import {
  ResponsiveContainer,
  ComposedChart,
  Area,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  Legend,
  PieChart,
  Pie,
  Cell,
} from 'recharts';
import { LoanChartProps } from '../types';
import { formatCurrency, formatManYen } from '../utils/calculator';

type ChartTabType = 'area' | 'pie';

const PIE_COLORS = ['#2563eb', '#f59e0b'];

// 静的スタイルの定数化（再レンダリング時のパフォーマンスと保守性の向上）
const TOOLTIP_CONTENT_STYLE = {
  backgroundColor: '#ffffff',
  borderRadius: '8px',
  border: '1px solid #e2e8f0',
  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
};

const TOOLTIP_LABEL_STYLE = {
  fontWeight: 'bold' as const,
  color: '#0f172a',
};

const LEGEND_WRAPPER_STYLE = {
  fontSize: '0.85rem',
};

const CHART_MARGIN = {
  top: 10,
  right: 20,
  left: 0,
  bottom: 0,
};

const AXIS_TICK_STYLE = {
  fontSize: 12,
  fill: '#64748b',
};

const LoanChart = ({ schedule = [], principal, totalInterest }: LoanChartProps) => {
  const [activeTab, setActiveTab] = useState<ChartTabType>('area');

  // Empty State: 計算中またはスケジュールが存在しない場合
  if (!schedule || schedule.length === 0) {
    return (
      <div className="chart-card">
        <div
          className="chart-container"
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#64748b',
            fontSize: '0.95rem',
          }}
        >
          データがありません
        </div>
      </div>
    );
  }

  // グラフ用データ（万円換算）
  const chartData = schedule.map((item) => ({
    yearLabel: `${item.year}年目`,
    残債: Math.round(item.balance / 10000),
    元金累計: Math.round(item.cumulativePrincipal / 10000),
    利息累計: Math.round(item.cumulativeInterest / 10000),
  }));

  // 円グラフ用データ
  const totalPayment = principal + totalInterest;
  const principalRatio = totalPayment > 0 ? Math.round((principal / totalPayment) * 100) : 0;
  const interestRatio = totalPayment > 0 ? 100 - principalRatio : 0;

  const pieData = [
    { name: '借入元金', value: principal, percentage: principalRatio },
    { name: '利息総額', value: totalInterest, percentage: interestRatio },
  ];

  return (
    <div className="chart-card">
      <div className="chart-tabs">
        <button
          type="button"
          className={activeTab === 'area' ? 'chart-tab-btn chart-tab-btn-active' : 'chart-tab-btn'}
          onClick={() => setActiveTab('area')}
        >
          残債・返済累計推移
        </button>
        <button
          type="button"
          className={activeTab === 'pie' ? 'chart-tab-btn chart-tab-btn-active' : 'chart-tab-btn'}
          onClick={() => setActiveTab('pie')}
        >
          返済内訳（元金 vs 利息）
        </button>
      </div>

      <div className="chart-container">
        {activeTab === 'area' ? (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={chartData} margin={CHART_MARGIN}>
              <defs>
                <linearGradient id="colorPrincipal" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#059669" stopOpacity={0.7} />
                  <stop offset="95%" stopColor="#059669" stopOpacity={0.15} />
                </linearGradient>
                <linearGradient id="colorInterest" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#f59e0b" stopOpacity={0.7} />
                  <stop offset="95%" stopColor="#f59e0b" stopOpacity={0.15} />
                </linearGradient>
              </defs>
              <XAxis dataKey="yearLabel" tick={AXIS_TICK_STYLE} />
              <YAxis
                tickFormatter={(value: number) => `${value}万`}
                tick={AXIS_TICK_STYLE}
                width={70}
              />
              <Tooltip
                formatter={(value: number, name: string) => [
                  `${formatCurrency(Number(value) * 10000)}円 (${value}万円)`,
                  name,
                ]}
                labelStyle={TOOLTIP_LABEL_STYLE}
                contentStyle={TOOLTIP_CONTENT_STYLE}
              />
              <Legend verticalAlign="top" height={36} wrapperStyle={LEGEND_WRAPPER_STYLE} />
              {/* 元金累計と利息累計を積層(stackId)して返済総額の推移を直感的に表現 */}
              <Area
                type="monotone"
                dataKey="元金累計"
                stackId="cumulative"
                stroke="#059669"
                strokeWidth={2}
                fillOpacity={1}
                fill="url(#colorPrincipal)"
              />
              <Area
                type="monotone"
                dataKey="利息累計"
                stackId="cumulative"
                stroke="#f59e0b"
                strokeWidth={2}
                fillOpacity={1}
                fill="url(#colorInterest)"
              />
              {/* 残債推移は折れ線(Line)として独立描画し重なりによる視認性低下を防止 */}
              <Line
                type="monotone"
                dataKey="残債"
                stroke="#2563eb"
                strokeWidth={3}
                dot={{ r: 2, fill: '#2563eb' }}
                activeDot={{ r: 5 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={pieData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                innerRadius={70}
                outerRadius={105}
                paddingAngle={4}
                label={(entry) => `${entry.name}: ${entry.percentage}%`}
              >
                {pieData.map((_, index) => (
                  <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip
                formatter={(value: number) => [
                  `${formatCurrency(Number(value))}円 (${formatManYen(Number(value))})`,
                  '金額',
                ]}
                contentStyle={TOOLTIP_CONTENT_STYLE}
              />
              <Legend verticalAlign="bottom" height={36} wrapperStyle={LEGEND_WRAPPER_STYLE} />
            </PieChart>
          </ResponsiveContainer>
        )}
      </div>
    </div>
  );
};

export default LoanChart;

