    principal: 35000000,
    interestRate: 0.5,
    years: 35,
    repaymentType: 'equal-payment',
    bonusAmount: 0,
  });

  // 年次返済スケジュール一覧の開閉状態および表示間隔フィルター
  const [showSchedule, setShowSchedule] = useState<boolean>(false);
  const [filterInterval, setFilterInterval] = useState<'all' | '5years'>('all');

  // ローン計算のメモ化
  const result = useMemo(() => {
    return calculateLoan(inputs);
  }, [inputs]);

  // 年次スケジュールのフィルター表示（全期間 または 5年刻み）
  const filteredSchedule = useMemo(() => {
    if (filterInterval === '5years') {
      return result.schedule.filter(
        (item) => item.year % 5 === 0 || item.year === result.schedule.length
      );
    }
    return result.schedule;
  }, [result.schedule, filterInterval]);

  // CSVエクスポート処理
  const handleExportCsv = () => {
    const headers = [
      '年数',
      '年間元金返済(円)',
      '年間利息返済(円)',
      '元金累計(円)',
      '利息累計(円)',
      'ローン残債(円)',
    ];
    const rows = result.schedule.map((item) => [
      `${item.year}年目`,
      item.principalPaid,
      item.interestPaid,
      item.cumulativePrincipal,
      item.cumulativeInterest,
      item.balance,
    ]);
    const csvContent =
      '\uFEFF' + [headers.join(','), ...rows.map((row) => row.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `住宅ローン返済スケジュール_${inputs.years}年.csv`);
