          <div className="summary-item">
            <span className="summary-label">毎月の返済額</span>
            {inputs.repaymentType === 'equal-principal' &&
            result.monthlyPaymentMax &&
            result.monthlyPaymentMin ? (
              <>
                <div className="summary-value highlight-value">
                  <span>{formatCurrency(result.monthlyPaymentMax)}</span>
                  <span className="summary-unit">円 〜 </span>
                  <span>{formatCurrency(result.monthlyPaymentMin)}</span>
                  <span className="summary-unit">円 / 月</span>
                </div>
                <span className="form-helper">
                  ※初回 {formatCurrency(result.monthlyPaymentMax)}円 → 最終回 {formatCurrency(result.monthlyPaymentMin)}円（順次減額）
                </span>
              </>
            ) : (
              <>
                <div className="summary-value highlight-value">
                  <span>{formatCurrency(result.monthlyPayment)}</span>
                  <span className="summary-unit">円 / 月</span>
                </div>
                <span className="form-helper">※全期間定額（元利均等）</span>
              </>
