          </div>

          <div className="summary-item">
            <span className="summary-label">ボーナス月加算額</span>
            <div className="summary-value">
              <span>{formatCurrency(result.bonusPayment)}</span>
              <span className="summary-unit">円 / 回</span>
            </div>
            {result.bonusPayment > 0 ? (
              <span className="form-helper">
                年2回（加算時: {formatCurrency(result.monthlyPayment + result.bonusPayment)}円）
