              <span className="form-helper">ボーナス払いなし</span>
            )}
          </div>

          <div className="summary-item">
            <span className="summary-label">総返済額</span>
            <div className="summary-value">
              <span>{formatManYen(result.totalPayment)}</span>
            </div>
            <span className="form-helper">{formatCurrency(result.totalPayment)}円</span>
          </div>

          <div className="summary-item">
            <span className="summary-label">利息総額</span>
            <div className="summary-value warning-value">
              <span>{formatManYen(result.totalInterest)}</span>
            </div>
            <span className="form-helper">{formatCurrency(result.totalInterest)}円</span>
          </div>
        </div>
      </section>

      {/* メインレイアウト: 入力フォーム ＆ グラフ表示 */}
      <div className="simulator-layout">
        <div>
          <LoanInputForm inputs={inputs} onChange={setInputs} />
        </div>

        <div>
          <LoanChart
