            principal={inputs.principal}
            totalInterest={result.totalInterest}
          />

          {/* 年次スケジュール詳細テーブル */}
          <div className="table-card">
            <div className="table-header-bar">
              <div className="table-title-group">
                <h2 className="table-title">年次返済スケジュール一覧</h2>
                <span className="badge badge-primary">{inputs.years}年間</span>
              </div>
              <button
                type="button"
                className="toggle-btn"
                onClick={() => setShowSchedule(!showSchedule)}
                aria-expanded={showSchedule}
              >
                <span>{showSchedule ? '閉じる' : '詳細表を表示'}</span>
                {showSchedule ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
              </button>
            </div>

            {showSchedule && (
              <>
                <div className="chart-tabs">
                  <button
                    type="button"
                    className={
                      filterInterval === 'all'
                        ? 'chart-tab-btn chart-tab-btn-active'
                        : 'chart-tab-btn'
                    }
                    onClick={() => setFilterInterval('all')}
                  >
                    全期間（1年ごと）
                  </button>
                  <button
                    type="button"
                    className={
                      filterInterval === '5years'
                        ? 'chart-tab-btn chart-tab-btn-active'
                        : 'chart-tab-btn'
                    }
                    onClick={() => setFilterInterval('5years')}
                  >
                    5年刻み表示
                  </button>
                  <button
                    type="button"
                    className="toggle-btn"
                    onClick={handleExportCsv}
                  >
                    <Download size={14} />
                    <span>CSV保存</span>
                  </button>
                </div>

                <div className="schedule-table-wrapper">
                  <table className="schedule-table">
                    <thead className="table-header">
                      <tr>
                        <th>年数</th>
                        <th>年間元金返済</th>
                        <th>年間利息返済</th>
                        <th>元金累計</th>
                        <th>利息累計</th>
                        <th>ローン残債</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredSchedule.map((item) => (
                        <tr key={item.year} className="table-row">
                          <td>{item.year}年目</td>
                          <td>{formatCurrency(item.principalPaid)}円</td>
                          <td>{formatCurrency(item.interestPaid)}円</td>
                          <td>{formatCurrency(item.cumulativePrincipal)}円</td>
                          <td>{formatCurrency(item.cumulativeInterest)}円</td>
                          <td className="font-semibold">{formatCurrency(item.balance)}円</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;
